def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = []
    for r in range(rows):
        row = grid[r]
        pattern = [8] * 7
        for c in range(7):
            # Collect candidate values from columns c, c+7, c+14...
            vals = []
            for k in range(c, cols, 7):
                if row[k] != 8:
                    vals.append(row[k])
            # If we have no candidates (all 8s), we leave it as 8.
            # If we have candidates, pick the first one (prioritized in order of appearance).
            if vals:
                pattern[c] = vals[0]

        # Reconstruct the row using the pattern where 8 was present
        new_row = []
        for c in range(cols):
            if row[c] == 8:
                new_row.append(pattern[c % 7])
            else:
                new_row.append(row[c])
        result.append(new_row)
    return result
